#' Distributions of the interim, Phase 2 and Phase 3 totals within one group
#'
#' Builds the three quantities needed to evaluate a 2-in-1 design with count
#' endpoints in a single treatment group. Counts are generated by an additive
#' gamma frailty model in which patient \code{i} carries a shared component
#' \code{G0} with shape \code{shared} and an endpoint specific component with
#' shape \code{dispersion - shared}, and the count for endpoint \code{k} is
#' Poisson with mean proportional to the sum of the two components. Each
#' endpoint is then marginally negative binomial with its own dispersion, while
#' the two endpoints are correlated within a patient through the shared
#' component.
#'
#' The Phase 3 total splits into a contribution from the patients already
#' followed at the interim analysis and a contribution from the remaining
#' patients. Given the shared component, the first contribution and the interim
#' count are conditionally independent Poisson variables, so the conditional
#' distribution of the first contribution given the interim count is again
#' negative binomial. That closure is what makes the joint propagation
#' deterministic.
#'
#' The retained supports are chosen from the marginal distributions. A row of
#' the returned transition matrix therefore sums to slightly less than one when
#' the interim count sits far enough in the upper tail that the conditional
#' distribution of the Phase 3 total reaches beyond \code{tmax}. Those rows carry
#' negligible probability, so the mass discarded after weighting by the
#' distribution of the interim count stays at the level of the truncation
#' tolerance used to choose the supports.
#'
#' @param rate1 Mean count per patient for the Phase 2 endpoint in this group.
#' @param rate2 Mean count per patient for the Phase 3 endpoint in this group.
#' @param dispersion1 Dispersion of the Phase 2 endpoint.
#' @param dispersion2 Dispersion of the Phase 3 endpoint.
#' @param shared Shape of the frailty component shared by the two endpoints,
#'   which must not exceed either dispersion. A value of zero makes the two
#'   endpoints independent and the largest admissible value gives the strongest
#'   attainable correlation.
#' @param n1 Number of patients in this group at the interim analysis.
#' @param n2 Number of patients in this group in the small trial.
#' @param n3 Number of patients in this group in the large trial.
#' @param amax Largest count retained on the support of the interim total.
#' @param smax Largest count retained on the support of the Phase 2 total.
#' @param tmax Largest count retained on the support of the Phase 3 total.
#' @return A list with components \code{interim}, the probability mass function
#'   of the interim total; \code{extra}, the probability mass function of the
#'   Phase 2 endpoint count contributed by the patients enrolled after the
#'   interim analysis; and \code{transition}, a matrix whose row \code{a} holds
#'   the conditional distribution of the Phase 3 total given an interim total of
#'   \code{a - 1}. Rows sum to one up to the mass discarded by truncation.
#' @export
#' @examples
#' out <- count_transition(rate1 = 3, rate2 = 0.6, dispersion1 = 0.5,
#'                         dispersion2 = 1.5, shared = 0.25,
#'                         n1 = 50, n2 = 80, n3 = 250,
#'                         amax = 300, smax = 400, tmax = 200)
#' sum(out$interim)
#' range(rowSums(out$transition))
count_transition <- function(rate1, rate2, dispersion1, dispersion2, shared,
                             n1, n2, n3, amax, smax, tmax) {
  if (shared < 0 || shared > min(dispersion1, dispersion2)) {
    stop("'shared' must lie between 0 and the smaller of the two dispersions.")
  }
  if (n1 > n2 || n2 > n3) {
    stop("'n1', 'n2' and 'n3' must be non-decreasing.")
  }
  scale1 <- rate1 / dispersion1
  scale2 <- rate2 / dispersion2
  shape0 <- n1 * shared
  interim <- nb_pmf_cpp(n1 * dispersion1, n1 * rate1, as.integer(amax))
  extra <- nb_pmf_cpp((n2 - n1) * dispersion1, (n2 - n1) * rate1, as.integer(smax))
  pmf_shared <- nb_pmf_cpp(shape0, shape0 * scale1, as.integer(amax))
  pmf_specific <- nb_pmf_cpp(n1 * (dispersion1 - shared),
                             n1 * (dispersion1 - shared) * scale1, as.integer(amax))
  pmf_late_shared <- nb_pmf_cpp(n1 * (dispersion2 - shared),
                                n1 * (dispersion2 - shared) * scale2,
                                as.integer(tmax))
  pmf_new <- nb_pmf_cpp((n3 - n1) * dispersion2, (n3 - n1) * rate2, as.integer(tmax))
  kernel <- convolve_pmf(pmf_late_shared, pmf_new, as.integer(tmax))
  counts <- seq(0, amax)
  shapes <- counts + shape0
  means <- shapes * scale2 / (1 + scale1)
  linked <- nb_pmf_matrix_cpp(as.numeric(shapes), as.numeric(means),
                              as.integer(tmax))
  linked <- convolve_rows_cpp(linked, kernel, as.integer(tmax))
  weight <- posterior_weight_cpp(pmf_shared, pmf_specific)
  list(interim = interim, extra = extra, transition = weight %*% linked)
}
